/**
 * Estimate (spend-proxy) and miscellaneous (spend_generic) rows.
 * The limit is a share of transaction count, not of emissions or spend.
 *
 * Web copy of shared/estimateScreeningPolicy.js. Create React App cannot
 * import the repo-root module. Keep the two files in sync.
 */
export const ESTIMATE_SHARE_THRESHOLD = 0.01;

export const ESTIMATE_RATIONALE = 'These rows are estimate-based spend proxies or the miscellaneous factor spend_generic (0.001 kgCO2e per INR). The miscellaneous factor is a screening residual for unclassified spend, not a CEA, IPCC, or EEIO factor: 0.001 kgCO2e/INR is 1 kgCO2e per ₹1,000 and is used only after a named activity, material, fuel, electricity, or courier factor does not match. Spend-proxy rows divide a rupee amount by a unit price because the voucher has no kWh, litre, kg, or tonne-km. Keep this set under 1% of transaction count by entering the activity quantity or a cited factor. The check is count divided by total transactions.';

export const ESTIMATE_METHODS = ['spend_proxy', 'spend-proxy', 'tier_2_spend'];
export const ESTIMATE_FLAGS = [
  'tier2_spend_proxy_requires_activity_units',
  'unknown_material_eeio_spend',
  'sector_material_spend_proxy',
  'missing_activity_unit'
];

const normalizeFlags = (complianceFlags) => {
  if (Array.isArray(complianceFlags)) {
    return complianceFlags.map((flag) => String(flag));
  }
  if (complianceFlags && typeof complianceFlags === 'object') {
    return Object.entries(complianceFlags)
      .filter(([, value]) => value)
      .map(([key]) => key);
  }
  return [];
};

export const isEstimateOrMiscellaneousTransaction = (transaction = {}) => {
  const footprint = transaction.carbonFootprint && typeof transaction.carbonFootprint === 'object'
    ? transaction.carbonFootprint
    : transaction;
  const method = String(footprint.quantificationMethod || footprint.calculationMethod || '').toLowerCase();
  const factorId = String(footprint.factorLineage?.id || footprint.factorId || '');
  const flags = normalizeFlags(footprint.complianceFlags);

  const basis = String(transaction.metadata?.carbonInputBasis || '').toLowerCase();
  if (factorId === 'spend_generic') {
    return { match: true, reason: 'miscellaneous_factor' };
  }
  if (basis === 'spend' || flags.includes('user_supplied_spend_basis')) {
    return { match: false, reason: null };
  }
  if (ESTIMATE_METHODS.includes(method)) {
    return { match: true, reason: 'estimate_spend_proxy' };
  }
  if (flags.some((flag) => ESTIMATE_FLAGS.includes(flag))) {
    return { match: true, reason: 'estimate_flag' };
  }
  return { match: false, reason: null };
};

export const buildEstimateScreeningSummary = (estimateCount, transactionCount) => {
  const count = Math.max(0, Number(estimateCount) || 0);
  const total = Math.max(0, Number(transactionCount) || 0);
  const share = total > 0 ? count / total : 0;
  const exceedsThreshold = total > 0 && share >= ESTIMATE_SHARE_THRESHOLD;
  const sharePercent = Math.round(share * 10000) / 100;
  return {
    transactionCount: total,
    estimateOrMiscellaneousCount: count,
    share,
    sharePercent,
    threshold: ESTIMATE_SHARE_THRESHOLD,
    thresholdPercent: ESTIMATE_SHARE_THRESHOLD * 100,
    exceedsThreshold,
    rationale: ESTIMATE_RATIONALE,
    notification: exceedsThreshold
      ? `Estimate or miscellaneous calculations are ${count} of ${total} transactions (${sharePercent}%), above the 1% limit. ${ESTIMATE_RATIONALE}`
      : null
  };
};

export const summarizeEstimateScreening = (transactions = []) => {
  const matched = (Array.isArray(transactions) ? transactions : [])
    .filter((row) => isEstimateOrMiscellaneousTransaction(row).match).length;
  return buildEstimateScreeningSummary(matched, Array.isArray(transactions) ? transactions.length : 0);
};

export const ESTIMATE_MONGO_OR = [
  { 'carbonFootprint.quantificationMethod': { $in: ESTIMATE_METHODS } },
  { 'carbonFootprint.calculationMethod': { $in: ESTIMATE_METHODS } },
  { 'carbonFootprint.factorLineage.id': 'spend_generic' },
  { 'carbonFootprint.complianceFlags': { $in: ESTIMATE_FLAGS } }
];
